// MieoSQL app logo — iOS-style squircle (Apple blue gradient + white DB
// cylinder). Single source of truth for every in-app logo surface
// (titlebar, welcome state, about). The OS bundle icon lives in
// `apps/mieosql-desktop/icons/icon.png` (1024px, generated by
// `scripts/gen-icon.py`); this SVG mirrors that artwork 1:1.

import { useId } from "react";

export function AppLogo({
  size = 16,
  radius = 5,
  className,
}: {
  /** Box size in px. */
  size?: number;
  /** Corner radius in px — ~30% reads as iOS squircle at small sizes. */
  radius?: number;
  className?: string;
}) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
  const bg = `mieo-bg-${uid}`;
  const gloss = `mieo-gloss-${uid}`;
  const clip = `mieo-clip-${uid}`;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 1024 1024"
      role="img"
      aria-label="MieoSQL"
      className={className}
      style={{ borderRadius: radius, display: "block", overflow: "hidden" }}
    >
      <defs>
        <linearGradient id={bg} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#3AA1FF" />
          <stop offset="0.45" stopColor="#007AFF" />
          <stop offset="1" stopColor="#0052CC" />
        </linearGradient>
        <radialGradient id={gloss} cx="0.5" cy="0.22" r="0.75">
          <stop offset="0" stopColor="#FFFFFF" stopOpacity="0.16" />
          <stop offset="1" stopColor="#FFFFFF" stopOpacity="0" />
        </radialGradient>
        <clipPath id={clip}>
          <rect width="1024" height="1024" rx="230" />
        </clipPath>
      </defs>
      <g clipPath={`url(#${clip})`}>
        <rect width="1024" height="1024" fill={`url(#${bg})`} />
        <rect width="1024" height="1024" fill={`url(#${gloss})`} />
        <rect x="287" y="290" width="450" height="470" fill="#FFFFFF" />
        <rect x="287" y="482" width="450" height="16" fill="#0064DD" />
        <rect x="287" y="606" width="450" height="16" fill="#005BCC" />
        <ellipse
          cx="512"
          cy="290"
          rx="225"
          ry="76"
          fill="#FFFFFF"
          stroke="#BFD6F8"
          strokeWidth="5"
        />
        <ellipse
          cx="512"
          cy="760"
          rx="225"
          ry="76"
          fill="#E4EFFF"
          stroke="#BED4F5"
          strokeWidth="4"
        />
        <rect
          x="3"
          y="3"
          width="1018"
          height="1018"
          rx="227"
          fill="none"
          stroke="#FFFFFF"
          strokeOpacity="0.28"
          strokeWidth="5"
        />
      </g>
    </svg>
  );
}
